const N=8;
function placements(L){const out=[];for(let r=0;r<N;r++)for(let c=0;c+L<=N;c++){let m=0n,cells=[];for(let k=0;k<L;k++){m|=1n<<BigInt(r*N+c+k);cells.push(r*N+c+k);}out.push({m,cells});}for(let c=0;c<N;c++)for(let r=0;r+L<=N;r++){let m=0n,cells=[];for(let k=0;k<L;k++){m|=1n<<BigInt((r+k)*N+c);cells.push((r+k)*N+c);}out.push({m,cells});}return out;}
function halo(m){let h=0n;for(let i=0;i<64;i++){if(!((m>>BigInt(i))&1n))continue;const r=(i/8)|0,c=i%8;for(let dr=-1;dr<=1;dr++)for(let dc=-1;dc<=1;dc++){const rr=r+dr,cc=c+dc;if(rr<0||rr>7||cc<0||cc>7)continue;h|=1n<<BigInt(rr*8+cc);}}return h;}
const ALL={4:placements(4),3:placements(3),2:placements(2)};
function count(riftMask){
 const f=L=>ALL[L].filter(p=>(p.m&riftMask)===0n).map(p=>({m:p.m,h:halo(p.m)}));
 const P4=f(4),P3=f(3),P2=f(2);
 let total=0;
 for(let a=0;a<P4.length;a++)for(let b=0;b<P3.length;b++){
  if((P3[b].m&P4[a].h)!==0n)continue;
  const h1=P4[a].h|P3[b].h;
  for(let c=b+1;c<P3.length;c++){
   if((P3[c].m&h1)!==0n)continue;
   const h2=h1|P3[c].h;
   for(let d=0;d<P2.length;d++) if((P2[d].m&h2)===0n) total++;
  }
 }
 return {total,sizes:[P4.length,P3.length,P2.length]};
}
// xorshift-ish deterministic sampling
let s=12345;const rnd=()=>{s^=s<<13;s^=s>>>17;s^=s<<5;s>>>=0;return s/4294967296;};
const t0=Date.now();
const res=[];
for(let trial=0;trial<10;trial++){
 const set=new Set();while(set.size<3)set.add(Math.floor(rnd()*64));
 let mask=0n;for(const i of set)mask|=1n<<BigInt(i);
 const r=count(mask);
 res.push([[...set].join(","),r.total,r.sizes.join("/")]);
}
for(const r of res)console.log(r.join("  "));
console.log("ms",Date.now()-t0);
// extremes: 3 corner cells vs 3 central cells
const corners=(a)=>{let m=0n;for(const i of a)m|=1n<<BigInt(i);return m;};
console.log("corners 0,7,56 ->",count(corners([0,7,56])).total);
console.log("center 27,28,35 ->",count(corners([27,28,35])).total);
console.log("center spread 18,27,36 ->",count(corners([18,27,36])).total);
'
